def transform(grid):
    """Find translated copies of the non-background marker shape and recolor them."""
    h, w = len(grid), len(grid[0])
    # Marker is the distinct color 3/7; the binary field's zeros are where copies go.
    colors = {v for row in grid for v in row}
    marker = next(v for v in colors if v in (3, 7))
    target = 0
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for dr in range(h-sh+1):
        for dc in range(w-sw+1):
            if all(grid[dr+r][dc+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr+r][dc+c] = marker
    return out

